WITH ins10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, $h10$الفصل الثاني - التأسيس والترخيص والقيد بالسجل - ثانيًا - قيد الأشخاص الطبيعيين فى السجل$h10$, $t10_0$المادة العاشرة - شروط قيد وتجديد قيد وإعادة قيد الخبراء الاكتواريين$t10_0$, $b10_0$يشترط فى الشخص الطبيعى الراغب فى القيد كخبير اكتوارى فى السجل المعد لهذا الغرض لدى الهيئة ، أن يتوافر فيه الشروط الآتية :
1- أن يكون محمود السيرة ، حسن السمعة.
2- أن يكون حاصلاً على إحدى الدرجات الآتية :
(أ) درجة زميل أو رفيق من أحد المعاهد الآتية :
معهد وكلية الخبراء الاكتواريين بالمملكة المتحدة.
جمعية الخبراء الاكتواريين بالولايات المتحدة الأمريكية.
(ب) درجة مهنية تالية لمرحلة الدراسة الأولى فى العلوم الاكتوارية من إحدى جمعيات أو معاهد الخبراء الاكتواريين ، معادلة للشهادات الواردة فى البند (أ) التى يعتمدها مجلس إدارة الهيئة.
3- ألا يكون به عارض من عوارض الأهلية.
4- ألا يكون قد صدر ضده تدابير إدارية من الهيئة - باستثناء الإنذار - خلال الثلاث سنوات السابقة على تاريخ تقديم طلب القيد.
5- ألا يكون قد صدر ضده حكم نهائى فى جناية أو فى جنحة فى جريمة مخلة بالشرف أو الأمانة ، أو فى إحدى الجرائم المنصوص عليها فى أى من قوانين التجارة أو الشركات أو أحد القوانين المنظمة للأنشطة المالية غير المصرفية أو حكم بإشهار إفلاسه ما لم يكن قد رد إليه اعتباره ، وذلك خلال الخمس سنوات السابقة على تاريخ تقديم طلب القيد.
6- ألا يكون قد فصل من عمله بحكم أو بقرار تأديبى نهائى أو صدر قرار بشطب قيد اسمه من أى من سجلات المهن التى تنظمها القوانين لأمور تمس الأمانة أو الشرف ما لم يمض على صدور الحكم أو القرار ثلاث سنوات.
7- اجتياز الاختبار الذى تعقده الهيئة فى هذا الشأن.
8- الالتزام بقواعد ومعايير الخبرة الاكتوارية المعتمدة من مجلس إدارة الهيئة فى مباشرته للنشاط.
9- التسجيل على المنصة الالكترونية للمهنيين.
10- الالتزام بقواعد وضوابط التطوير المهنى المستمر الصادرة عن الهيئة.
11- ألا يكون مقيدًا لدى الهيئة بأى من سجلات المهن التأمينية المنصوص عليها بقانون التأمين الموحد. ويشترط لتجديد قيد أو إعادة قيد الخبير الاكتوارى بالسجل استمرار توافر الشروط المنصوص عليها بهذه المادة.$b10_0$
