WITH ins12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, $h12$الفصل الثاني - التأسيس والترخيص والقيد بالسجل - ثانيًا - قيد الأشخاص الطبيعيين فى السجل$h12$, $t12_0$المادة الثانية عشرة - وثيقة تأمين المسئولية المهنية$t12_0$, $b12_0$على طالب الترخيص والقيد أو تجديد القيد أو إعادة القيد بالسجل أن يقدم قبل قيده أو تجديد قيده أو إعادة قيده بالسجل وثيقة تأمين مسئولية مهنية لدى إحدى شركات التأمين العاملة فى مصر ، يتم تحديد قيمتها وفقًا لما يلي :
أولاً - بالنسبة لشركات الخبرة الاكتوارية :
1- عند القيد :
وثيقة بحدود مسئولية قدرها 5 ملايين جنيه مصرى عن العام الواحد ولمدة خمس سنوات (خلال مدة الترخيص).
2- عند تجديد القيد أو إعادة القيد :
يتم تجديد الوثيقة فى ضوء حجم الأعمال التى قامت بها الشركة عن العام السابق على التجديد بما يعادل خمسمائة ألف جنيه عن كل شركة تأمين أو إعادة تأمين وخمسين ألف جنيه عن كل صندوق تأمين خاص أو حكومي ، وبحد أدنى 5 ملايين جنيه مصرى عن العام الواحد ولمدة خمس سنوات.
ثانيًا - بالنسبة للخبير الاكتوارى من الأشخاص الطبيعيين :
1- عند القيد :
تحدد قيمة ثابتة بحدود مسئولية قدرها مليون جنيه مصرى عن العام الواحد للخبير الذى يرغب فى مزاولة نشاطه لشركات التأمين وإعادة التأمين وخمسمائة ألف جنيه لمن يرغب فى مزاولة النشاط لصناديق التأمين الخاصة أو الحكومية ولمدة خمس سنوات (خلال مدة الترخيص).
2- عند تجديد القيد أو إعادة القيد :
تحدد قيمة الوثيقة فى ضوء حجم الأعمال التى قام بها الخبير عن العام السابق على التجديد بما يعادل خمسمائة ألف جنيه عن كل شركة تأمين أو إعادة تأمين وخمسين ألف جنيه عن كل صندوق تأمين خاص أو حكومي ، وبحد أدنى مليون جنيه عن العام الواحد ولمدة خمس سنوات.
ويتعين على الخبير الاكتوارى أن يرفق بالوثيقة إفادات بالأتعاب والمقابل الذى حصل عليه ، على أن تكون معتمدة من كافة الأطراف التى تعامل معها خلال آخر خمس سنوات سابقة على تاريخ تقديم الطلب.
ثالثا - بالنسبة للخبير الاكتوارى التابع لشركات الخبرة الاكتوارية :
يكتفى بالنسبة للخبراء الاكتواريين الذين يعملون لدى شركات الخبرة الاكتوارية وكذا القائم بأعمال الإدارة التنفيذية لديها ، بأن يتم تغطيتهم من خلال وثيقة مهنية شاملة وفقًا للبند أولاً من هذه المادة.
رابعا - بالنسبة للخبير الاكتوارى التابع لمنشآت التأمين وإعادة التأمين :
تلتزم منشآت التأمين وإعادة التأمين التى يعمل الخبراء الاكتواريين لحسابها بتحمل المسئولية المدنية المقررة عن أخطائهم قبل حملة الوثائق أو المستفيدين منها أو الغير فى التأمينات الصادرة عنها.
وفى جميع الأحوال ، لا يدخل فى تقدير حجم الأعمال لوثيقة تأمين المسئولية المهنية ، أعمال المراجعة على النظراء (Peer Review) .$b12_0$
  FROM laws WHERE law_no = 56 AND law_year = 2026 AND kind = 'board_decision'
