WITH ins19_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 19, 0, $h19$الفصل الثالث - قواعد مزاولة نشاط الخبرة الاكتوارية والتزامات الخبراء الذين يزاولون هذا النشاط$h19$, $t19_0$المادة التاسعة عشرة - مواعيد إعداد وعرض وتقديم القوائم المالية والمستندات المرفقة بها للهيئة$t19_0$, $b19_0$يتعين على الشركة موافاة الهيئة قبل شهر على الأقل من موعد انعقاد الجمعية العامة بالقوائم المالية السنوية والإفصاحات المرفقة بها وفقًا لمعايير المحاسبة المصرية ، وتقرير بشأنها من أحد مراقبى الحسابات المقيدين بالقسم الأول من سجل مراقبى الحسابات المنظم بقرار مجلس إدارة الهيئة رقم (244) لسنة 2023 المشار إليه ، وتقرير مجلس الإدارة عن نشاط الشركة ، وموعد ومكان انعقاد الجمعية العامة وجدول أعمالها ، وجميع المستندات التى تقدم إلى المساهمين عن أعمال الشركة.
وللهيئة إبداء ملاحظاتها على القوائم المالية ، وكذا على أى من البيانات والمستندات الواردة بهذا القرار وإخطار الشركة بملاحظاتها ، على أن يعرض ذلك على الجمعية العامة للشركة.
وتلتزم الشركة بموافاة الهيئة بالقوائم المالية السنوية لها خلال خمسة وأربعين يومًا من تاريخ انتهاء الثلاثة أشهر التالية لانتهاء السنة المالية مرفقًا بها المستندات الآتية :
1- تقرير مراقب الحسابات عن تلك القوائم حال تعديلها من قبل الجمعية العامة للشركة.
2- بيان بالأعمال والتقارير الاكتوارية التى قامت بها خلال العام.
3- بيان بعملائها الذين تعاملت معهم خلال السنة المالية المنقضية وبيان بإيراداتها المستحقة والمحصلة عن الأعمال والتقارير الاكتوارية التى قامت بها لكل عميل على حدة عن السنة المالية المنقضية موزعًا على كل فرع تأميني ولإجمالى الفروع.$b19_0$
  FROM laws WHERE law_no = 56 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins19_0;

WITH ins20_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 20, 0, $h20$الفصل الثالث - قواعد مزاولة نشاط الخبرة الاكتوارية والتزامات الخبراء الذين يزاولون هذا النشاط$h20$, $t20_0$المادة العشرون - السجلات التى يتعين على الخبراء الاكتواريين إمساكها$t20_0$, $b20_0$يتعين على الخبراء الاكتواريين إمساك السجلات الآتية :
أولاً - سجل الأعمال والتقارير الاكتوارية :
ويقيد به بيانات جميع الأعمال والتقارير الاكتوارية التى قام الخبير بها ، ويتضمن - بحد أدنى – البيانات الآتية :
1- اسم العميل وعنوانه .
2- فرع التأمين محل إعداد الدراسة والتقرير الاكتواري.
3- تاريخ التكليف بالقيام بالمهمة ، وتاريخ تقديم التقرير إلى العميل.
4- اسم الخبير التابع لشركة الخبرة الذى قام بإجراء الدراسة وإعداد التقرير الاكتواري.
5- الأتعاب أو المقابل الذى حصل عليه الخبير الذى قام بإجراء الدراسة وإعداد التقرير الاكتواري.
6- أى بيانات أخرى تطلبها الهيئة.
ثانيا - سجل الخبراء (بالنسبة لشركات الخبرة الاكتوارية) :
ويقيد به بيانات كل خبير اكتوارى التحق بالعمل لدى الشركة ، ويتضمن - بحد أدنى - البيانات الآتية :
1- اسم الخبير ، ونوعه ، وجنسيته ، ورقمه القومي ، وعنوان محل إقامته.
2- رقم وتاريخ قيده ، وتاريخ آخر تجديد قيد أو إعادة قيد لدى الهيئة.
3- تاريخ التحاقه بالعمل لدى الشركة وأى تغييرات طرأت على حالته بالشركة.
4- التدابير السابق توقيعها ضده (حال وجودها).
5- أى بيانات أخرى تطلبها الهيئة.
ثالثًا - أى سجلات أخرى تحددها الهيئة .$b20_0$
  FROM laws WHERE law_no = 56 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins20_0;

WITH ins21_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 21, 0, $h21$الفصل الثالث - قواعد مزاولة نشاط الخبرة الاكتوارية والتزامات الخبراء الذين يزاولون هذا النشاط$h21$, $t21_0$المادة الحادية والعشرون - التزامات الخبراء الاكتواريين$t21_0$, $b21_0$يجب على الخبير الاكتوارى مراعاة مبادئ النزاهة والاستقامة والأمانة والعدالة وحسن التصرف وبذل عناية الرجل الحريص فى جميع أعماله وتصرفاته والامتناع عن القيام بأى فعل ينطوى على إساءة إلى غيره من الخبراء أو العملاء أو منشآت التأمين وإعادة التأمين أو مهنة الخبرة الاكتوارية بوجه عام.
ويتعين على الخبير الاكتوارى مباشرة أعمال الخبرة وفقًا لأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذًا له ، وذلك مع الالتزام - بحد أدنى – بالضوابط الآتية :
1- أن يكون على علم ووعى بالتشريعات التأمينية والقواعد المنظمة للسوق وكذا القرارات الصادرة عن الهيئة ومتابعة ما يطرأ عليها من تعديلات والعمل على تطبيقها بدقة وعدم مخالفتها.
2- الإشارة إلى أنه «خبير اكتواري» فى أى عمل من أعماله ، وأن يقرن اسمه برقم قيده فى السجل ، وذلك فى جميع المكاتبات والشهادات والتقارير الصادرة عنه.
3- الالتزام بالقرارات الصادرة عن الهيئة فى شأن القواعد والمعايير الفنية المنظمة للخبرة الاكتوارية .
4- عدم ارتكاب أية مخالفات مهنية لإحدى الجهات الاكتوارية الأعضاء بالاتحاد الدولى للخبرة الاكتوارية.
5- التوقيع على كافة التقارير الصادرة عنه ، وإذا كان التقرير صادرًا عن شركة خبرة فيجب أن يكون موقعًا من القائم بالإدارة التنفيذية بالشركة وكذا الخبير الذى قام بالدراسة والفحص.
6- تجنب تعارض المصالح والإفصاح عنه فور العلم به للمتعاملين معه وذوى الشأن.
7- الحفاظ على سرية البيانات وخصوصية المعلومات التى يطلع عليها ، وعدم نشرها أو استخدامها خارج نطاق المهمة المكلف بها.
8- التعاون مع المحاكم أو الجهة المختصة وتقديم الإيضاحات عند طلبها.
9- الحياد والموضوعية وعدم الانحياز لأى طرف من أطراف النزاع عند إعداد تقرير للعرض على المحاكم المختصة أو هيئات التحكيم أو غير ذلك.
10- الامتناع عن الحصول على أى امتيازات مالية أو عينية غير معلنة سواء من عملائه أو من غيرهم.
11- توثيق مصادر المعلومات والمستندات التى بنى عليها الرأى والامتناع عن إبداء الرأى خارج حدود خبرته أو دون معلومات كافية.
12- استخدام الأساليب العلمية السليمة عند إبداء الرأى وأن يكون واضحًا ومسببًا ومبنيًا على وقائع وأدلة محددة ، وعدم الاعتماد على التخمين أو الافتراضات غير الموثقة.
13- مراعاة الضوابط الخاصة بمكافحة غسل الأموال وتمويل الإرهاب وانتشار التسلح وفقًا للتشريعات الصادرة فى هذا الشأن.
14- الاحتفاظ بجميع المستندات والعقود التى تم إبرامها مع منشآت التأمين لتقديم خدماته لها.
15- الامتناع عن القيام بأى عمل من شأنه تضليل أو الإضرار بأى من المتعاملين معه أو العاملين بقطاع التأمين أو الإخلال بحقوقهم.
16- إخطار الهيئة بالدعاوى القضائية أو التحكيمية التى يكون طرفًا فيها وتتعلق بممارسة نشاطه ، وكذا الأحكام الصادرة فيها.
17- موافاة الهيئة بأى بيانات أو مستندات أو سجلات تخص مزاولة النشاط ، متى طلب منه ذلك.$b21_0$
  FROM laws WHERE law_no = 56 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins21_0;

WITH ins22_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 22, 0, $h22$الفصل الثالث - قواعد مزاولة نشاط الخبرة الاكتوارية والتزامات الخبراء الذين يزاولون هذا النشاط$h22$, $t22_0$المادة الثانية والعشرون - التزامات منشآت التأمين وإعادة التأمين$t22_0$, $b22_0$يتعين على منشآت التأمين وإعادة التأمين حال تعاملها مع أى خبير اكتوارى مراعاة ما يلي :
1- إخطار الهيئة بكل مخالفة تنسب إلى الخبير الاكتواري ، وكذا كل دعوى قضائية أو تحكيمية يكون طرفًا فيها وتتعلق بممارسة نشاطه.
2- موافاة الهيئة سنويًا خلال ثلاثين يومًا على الأكثر من تاريخ انتهاء السنة المالية ببيان موضحًا به حجم أعمال الخبراء الاكتواريين (شخص طبيعى أو اعتباري) التى تمت لديها خلال السنة المنقضية ، وذلك وفقًا للنموذج المعد لهذا الغرض لدى الهيئة.
ويحظر على منشآت التأمين وإعادة التأمين عند تعاملها مع الخبراء الاكتواريين إسناد أى استشارة اكتوارية محلية إلى أى خبير ما لم يكن مقيدًا لدى الهيئة أو إلى أى خبير تربطه صلة قرابة حتى الدرجة الثانية مع أى من أعضاء مجلس إدارة الشركة أو مع أى من مساهميها أو يوجد مع أى منهم أية مصالح أو نفع مشترك.$b22_0$
  FROM laws WHERE law_no = 56 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins22_0;

WITH ins23_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 0, $h23$الفصل الرابع - إيقاف القيد والتدابير الإدارية$h23$, $t23_0$المادة الثالثة والعشرون - إيقاف قيد الخبير الاكتواري$t23_0$, $b23_0$يتعين على شركات الخبرة الاكتوارية وكذا منشآت التأمين وإعادة التأمين إخطار الهيئة حال إنهاء خدمة أى من الخبراء الاكتواريين العاملين لديها ، وذلك خلال أسبوع من تاريخ إنهاء الخدمة ، وتكون الشركة مسئولة عن جميع المخالفات المنسوبة إلى الخبير لحين إخطار الهيئة بإنهاء خدمته وأسباب ذلك.
ويتم إيقاف قيد الخبير بالسجل مؤقتًا فور ورود إخطار الشركة بإنهاء عمله ، ما لم يكن إنهاء العمل بسبب مخالفات تتعلق بدراسات اكتوارية أسند إليه القيام بها ، فتقوم الهيئة باتخاذ الإجراءات المقررة بشأن تلك المخالفات وفقًا لأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذًا له.
ولا يجوز للخبير خلال فترة إيقاف قيده ممارسة أى من أعمال الخبرة الاكتوارية إلا بعد إزالة أسباب إيقاف قيده وانتهاء مدة هذا الإيقاف أو التقدم إلى الهيئة بطلب لتعديل بيانات قيده بالسجل ، واستيفاء أى شروط متطلبة لذلك.
ويشطب الخبير الاكتوارى من السجل حال انتهاء مدة قيده دون قيامه بتعديل بياناته.$b23_0$
  FROM laws WHERE law_no = 56 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins23_0;

WITH ins24_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, $h24$الفصل الرابع - إيقاف القيد والتدابير الإدارية$h24$, $t24_0$المادة الرابعة والعشرون - التدابير الإدارية$t24_0$, $b24_0$للهيئة حال مخالفة الخبير الاكتوارى للقواعد الواردة بهذا القرار اتخاذ أى من التدابير الآتية :
1- الإنذار.
2- إلغاء الموافقة على فتح مكتب لمزاولة أعمال الخبرة الاكتوارية للأشخاص الطبيعيين أو الفرع للأشخاص الاعتبارية (إذا كان لديه فرع).
ولمجلس إدارة الهيئة إيقاف قيد الخبير الاكتوارى (شخص طبيعى أو اعتباري) لمدة لا تجاوز ثلاث سنوات أو شطب قيده من السجل فى حالة فقده أحد شروط التأسيس أو الترخيص أو القيد بالسجل بحسب الأحوال ، كما يجوز لمجلس إدارة الهيئة اتخاذ ذات التدبير بعد إجراء تحقيق من قبل الهيئة فى أى من الحالات الآتية :
1- إذا ثبت تقديمه أى بيانات جوهرية غير صحيحة مطلوبة وفقًا لأحكام قانون التأمين الموحد أو القرارات ذات الصلة نتيجة تعمد أو خطأ جسيم.
2- عدم التزامه بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة .
3- إذا ثبت قيامه بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوى على غش أو خطأ جسيم .$b24_0$
  FROM laws WHERE law_no = 56 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins24_0;

